  "inlineSchema": "// Schéma GabonMICE : authentification multi-rôles (Better Auth + Prisma).\n// Après modification : `npx prisma migrate dev` puis `npx prisma generate`.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Role {\n  TOURIST\n  ORGANIZER\n  PROVIDER\n  ADMIN\n}\n\nenum AccountStatus {\n  ACTIVE\n  PENDING\n  SUSPENDED\n}\n\nenum LabelStatus {\n  NONE\n  PENDING\n  GRANTED\n  REVOKED\n}\n\nmodel User {\n  id                 String            @id @default(cuid())\n  email              String            @unique\n  /// Identifiant de connexion (plugin username de Better Auth), stocké en minuscules.\n  username           String?           @unique\n  displayUsername    String?\n  name               String\n  phone              String?\n  image              String?\n  /// Better Auth gère la vérification d'e-mail sous forme de booléen.\n  emailVerified      Boolean           @default(false)\n  role               Role              @default(TOURIST)\n  status             AccountStatus     @default(ACTIVE)\n  /// Profil demandé par un utilisateur déjà inscrit (ex. touriste Google → organisateur).\n  requestedRole      Role?\n  mustChangePassword Boolean           @default(false)\n  lastLoginAt        DateTime?\n  /// Limitation des tentatives : 5 échecs → blocage 15 min.\n  failedLoginCount   Int               @default(0)\n  lockedUntil        DateTime?\n  createdAt          DateTime          @default(now())\n  updatedAt          DateTime          @updatedAt\n  accounts           Account[]\n  sessions           Session[]\n  touristProfile     TouristProfile?\n  organizerProfile   OrganizerProfile?\n  providerProfile    ProviderProfile?\n  auditLogs          AuditLog[]\n  demandes           Demande[]\n\n  @@map(\"user\")\n}\n\nmodel TouristProfile {\n  id       String  @id @default(cuid())\n  userId   String  @unique\n  user     User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  country  String?\n  company  String?\n  language String  @default(\"fr\")\n}\n\nmodel OrganizerProfile {\n  id           String  @id @default(cuid())\n  userId       String  @unique\n  user         User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  organization String\n  position     String?\n  website      String?\n}\n\nmodel ProviderProfile {\n  id             String             @id @default(cuid())\n  userId         String             @unique\n  user           User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  businessName   String\n  /// hôtel, salle, restaurant, agence, transport…\n  category       String\n  address        String?\n  latitude       Float?\n  longitude      Float?\n  labelStatus    LabelStatus        @default(PENDING)\n  labelGrantedAt DateTime?\n  labelExpiresAt DateTime?\n  documents      ProviderDocument[]\n}\n\n/// Justificatif de labellisation stocké dans Neon Object Storage (bucket « assets »).\n/// Seule la clé de l'objet est en base ; les liens de lecture sont signés à la demande.\nmodel ProviderDocument {\n  id                String          @id @default(cuid())\n  providerProfileId String\n  providerProfile   ProviderProfile @relation(fields: [providerProfileId], references: [id], onDelete: Cascade)\n  /// Clé de l'objet dans le bucket (providers/<profil>/<uuid>-<nom>)\n  key               String          @unique\n  fileName          String\n  contentType       String\n  size              Int\n  createdAt         DateTime        @default(now())\n\n  @@index([providerProfileId])\n}\n\nenum DemandeKind {\n  CONTACT\n  RESERVATION\n  DEVIS\n  EVENEMENT\n  LABELLISATION\n}\n\nenum DemandeStatus {\n  NEW\n  IN_PROGRESS\n  DONE\n  CANCELLED\n}\n\n/// Demande envoyée depuis un formulaire public (contact, réservation, devis,\n/// inscription d'événement, labellisation), suivie dans le back office.\nmodel Demande {\n  id           String        @id\n  kind         DemandeKind\n  /// Élément concerné (offre, salle, hôtel…) ou type d'événement.\n  subject      String\n  name         String\n  organisation String\n  email        String\n  phone        String\n  attendees    String?\n  message      String?\n  /// Champs complémentaires du formulaire (libellé → valeur).\n  details      Json?\n  status       DemandeStatus @default(NEW)\n  /// Note interne de l'administrateur, jamais visible du demandeur.\n  adminNote    String?\n  /// Compte connecté au moment de l'envoi, s'il y en avait un.\n  userId       String?\n  user         User?         @relation(fields: [userId], references: [id], onDelete: SetNull)\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n\n  @@index([status, createdAt])\n}\n\nmodel AuditLog {\n  id        String   @id @default(cuid())\n  userId    String?\n  user      User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  /// LOGIN, LOGIN_FAILED, LOGIN_LOCKED, ROLE_CHANGED, ACCOUNT_VALIDATED, LABEL_GRANTED…\n  action    String\n  details   Json?\n  ip        String?\n  createdAt DateTime @default(now())\n\n  @@index([action, createdAt])\n}\n\n// ---- Modèles Better Auth ----\n\nmodel Session {\n  id        String   @id\n  expiresAt DateTime\n  token     String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  ipAddress String?\n  userAgent String?\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"session\")\n}\n\n/// Comptes de connexion : \"credential\" (mot de passe haché bcrypt dans `password`) ou \"google\".\nmodel Account {\n  id                    String    @id\n  accountId             String\n  providerId            String\n  userId                String\n  user                  User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  accessToken           String?\n  refreshToken          String?\n  idToken               String?\n  accessTokenExpiresAt  DateTime?\n  refreshTokenExpiresAt DateTime?\n  scope                 String?\n  password              String?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  @@map(\"account\")\n}\n\nmodel Verification {\n  id         String   @id\n  identifier String\n  value      String\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@map(\"verification\")\n}\n",
